 @Autowired StemService stem;@Autowired StemRepository db;@Autowired StemValidator validator;@Autowired WorkspaceAccess access;
 @Autowired JdbcTemplate jdbc;@Autowired ObjectMapper json;@Autowired PlatformTransactionManager manager;
 @Autowired UserRepository users;@Autowired WorkspaceRepository workspaces;@Autowired WorkspaceMemberRepository members;@Autowired ClipProjectRepository projects;@Autowired ScriptVersionRepository versions;@Autowired SceneRepository scenes;@Autowired StatusHistoryRepository history;
 TransactionTemplate tx;String writer,reviewer,admin,workspace,project,version,scene;ScriptService scripts;MockMvc mvc;
 @BeforeEach void fixture(){tx=new TransactionTemplate(manager);tx.executeWithoutResult(s->{
  User w=user("WRITER",SystemRole.USER),r=user("REVIEWER",SystemRole.USER),a=user("ADMIN",SystemRole.ADMIN);writer=w.getId();reviewer=r.getId();admin=a.getId();
  Workspace ws=workspaces.saveAndFlush(Workspace.builder().name("TEST_ONLY "+UUID.randomUUID()).createdBy(a).build());workspace=ws.getId();
  members.saveAndFlush(WorkspaceMember.builder().workspace(ws).user(w).role(WorkspaceRole.WRITER).build());members.saveAndFlush(WorkspaceMember.builder().workspace(ws).user(r).role(WorkspaceRole.REVIEWER).build());
  ClipProject cp=projects.saveAndFlush(ClipProject.builder().title("TEST_ONLY not a verified lesson").subject(StemSubject.Math).gradeLevel("TEST_ONLY").owner(w).workspace(ws).build());project=cp.getId();
  ScriptVersion sv=versions.saveAndFlush(ScriptVersion.builder().project(cp).title("TEST_ONLY").versionNo(1).createdBy(w).build());version=sv.getId();
  Scene sc=scenes.saveAndFlush(Scene.builder().scriptVersion(sv).sceneType(SceneType.TITLE_HERO).title("TEST_ONLY").narration("TEST_ONLY").props("{}").orderNo(1).build());scene=sc.getId();
 });
 AuthService auth=mock(AuthService.class);when(auth.findUserOrThrow(anyString())).thenAnswer(i->users.findById(i.getArgument(0)).orElseThrow());
 scripts=new ScriptService(projects,versions,scenes,new SceneMapper(json,new ScenePropsValidator()),auth,mock(WorkspaceService.class),new StatusHistoryService(history),access);ReflectionTestUtils.setField(scripts,"stem",stem);
 mvc=MockMvcBuilders.standaloneSetup(new StemController(stem,validator)).addFilters(new StemRequestLimitFilter(json)).setControllerAdvice(new GlobalExceptionHandler()).build();
 }
 User user(String name,SystemRole role){return users.saveAndFlush(User.builder().fullName("TEST_ONLY "+name).username("p3"+UUID.randomUUID().toString().replace("-", "").substring(0,24)).email(UUID.randomUUID()+"@example.invalid").systemRole(role).build());}
 StemDtos.View create(){return stem.create(project,version,writer,new StemDtos.Create("stem.v1",0,"create-test-01"));}
 StemDtos.Save save(StemDtos.Brief b,List<StemDtos.Evidence> ev,int rev,String key){return new StemDtos.Save("stem.v1",rev,0,key,b,ev);}
 StemDtos.Assessment assessment(int br,String key){return new StemDtos.Assessment(br,0,null,0,null,List.of(new StemDtos.Criterion("TEST_ONLY","NOT_ASSESSED","TEST_ONLY no expert feedback",List.of())),key);}
 @Test void freshSchemaAndRlsHaveNoVerifiedOrStrictContent(){assertThat(jdbc.queryForObject("select count(*) from flyway_schema_history where success",Integer.class)).isEqualTo(26);assertThat(jdbc.queryForObject("select count(*) from pg_class where relname like 'stem_%' and relkind='r' and relrowsecurity",Integer.class)).isEqualTo(9);assertThat(jdbc.queryForObject("select count(*) from stem_settings where mode='STRICT'",Integer.class)).isZero();assertThat(jdbc.queryForObject("select count(*) from stem_catalog where status<>'DRAFT'",Integer.class)).isZero();}
 @Test void nullDraftReplayCasAndUnknownFieldApi()throws Exception{
  var a=create();assertThat(create().briefId()).isEqualTo(a.briefId());assertThat(a.brief().context().primary()).isNull();assertThat(a.verificationStatus()).isEqualTo("UNVERIFIED");
  stem.save(project,version,writer,save(StemDtos.empty(),List.of(),0,"save-test-01"));var again=stem.save(project,version,writer,save(StemDtos.empty(),List.of(),0,"save-test-01"));assertThat(again.revision()).isEqualTo(1);
  assertThatThrownBy(()->stem.save(project,version,writer,save(StemDtos.empty(),List.of(),0,"save-test-02"))).isInstanceOfSatisfying(ApiException.class,e->assertThat(e.getStatus().value()).isEqualTo(409));
  mvc.perform(put("/api/v1/scripts/{p}/versions/{v}/stem",project,version).principal(()->writer).contentType("application/json").content("{\"verified\":true}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.details.field").exists());
 }
 @Test void wrongActorAndAdminWithoutReviewerCannotAssess(){create();assertThatThrownBy(()->stem.save(project,version,admin,save(StemDtos.empty(),List.of(),0,"save-test-03"))).isInstanceOfSatisfying(ApiException.class,e->assertThat(e.getStatus().value()).isEqualTo(403));assertThatThrownBy(()->tx.execute(s->stem.prepare(projects.findById(project).orElseThrow(),versions.findById(version).orElseThrow(),admin,"SCRIPT",assessment(0,"review-test-01")))).isInstanceOfSatisfying(ApiException.class,e->assertThat(e.getStatus().value()).isEqualTo(403));}
 @Test void settingsPinNoBackfillAndStrictRefused(){create();String policy=tx.execute(s->db.createDraft(StemModels.Kind.POLICY,"TEST_ONLY-"+UUID.randomUUID(),1,null,null,json.createObjectNode()));stem.saveSettings(workspace,admin,new StemDtos.Settings(0,"ADVISORY",List.of(policy),policy,"settings-test-01",null));assertThat(stem.get(project,version,writer).brief().policyVersionId()).isNull();assertThat(stem.settings(workspace,writer).mode()).isEqualTo("ADVISORY");assertThatThrownBy(()->stem.saveSettings(workspace,admin,new StemDtos.Settings(1,"INVALID_MODE",List.of(policy),policy,"settings-test-02",null))).isInstanceOf(ApiException.class);assertThat(jdbc.queryForObject("select count(*) from stem_settings where mode='STRICT'",Integer.class)).isZero();}
 @Test void sceneDeletionPreservesOrphanAndExplicitEvidenceRetirement(){create();var e=new StemDtos.Evidence(null,scene,null,null,"S","TEST_ONLY");var saved=stem.save(project,version,writer,save(StemDtos.empty(),List.of(e),0,"save-orphan-01"));jdbc.update("delete from scenes where id=?",scene);var orphan=stem.get(project,version,writer);assertThat(orphan.findings()).anyMatch(f->f.ruleId().equals("TECH-EVIDENCE"));assertThat(orphan.evidence().get(0).sceneId()).isEqualTo(scene);stem.save(project,version,writer,save(StemDtos.empty(),List.of(),1,"save-orphan-02"));assertThat(jdbc.queryForObject("select count(*) from stem_evidence where id=? and retired",Integer.class,saved.evidence().get(0).id())).isEqualTo(1);}
 @Test void copyMapWrongRollsBackNewVersion(){create();int count=jdbc.queryForObject("select count(*) from script_versions where project_id=?",Integer.class,project);assertThatThrownBy(()->tx.executeWithoutResult(s->{ScriptVersion old=versions.findById(version).orElseThrow();old.setIsCurrent(false);versions.saveAndFlush(old);ScriptVersion next=versions.saveAndFlush(ScriptVersion.builder().project(old.getProject()).title("TEST_ONLY copy").versionNo(2).createdBy(old.getCreatedBy()).build());stem.copy(version,next.getId(),Map.of(scene,"wrong-scene"));})).isInstanceOf(ApiException.class);assertThat(jdbc.queryForObject("select count(*) from script_versions where project_id=?",Integer.class,project)).isEqualTo(count);}
 @Test void workflowApproveLinksExactlyOneExistingDecisionAndRetry(){create();tx.execute(s->scripts.submitForReview(project,writer));var req=new ReviewDecisionRequest("TEST_ONLY",assessment(0,"approve-test-01"));tx.execute(s->scripts.approve(project,req,reviewer));tx.execute(s->scripts.approve(project,req,reviewer));assertThatThrownBy(()->tx.execute(s->scripts.approve(project,new ReviewDecisionRequest("TEST_ONLY changed note",req.stemAssessment()),reviewer))).isInstanceOfSatisfying(ApiException.class,e->assertThat(e.getCode()).isEqualTo("STEM_IDEMPOTENCY_CONFLICT"));assertThat(jdbc.queryForObject("select count(*) from stem_assessments where version_id=?",Integer.class,version)).isEqualTo(1);assertThat(jdbc.queryForObject("select count(*) from status_histories where project_id=? and decision='APPROVED'",Integer.class,project)).isEqualTo(1);assertThat(jdbc.queryForObject("select verification_status from stem_assessments where version_id=?",String.class,version)).isEqualTo("UNVERIFIED");}
 @Test void requestChangesCopiesEvidenceByIdentityNotOrder(){create();stem.save(project,version,writer,save(StemDtos.empty(),List.of(new StemDtos.Evidence(null,scene,null,null,"E","TEST_ONLY")),0,"copy-setup-01"));tx.execute(s->scripts.submitForReview(project,writer));tx.execute(s->scripts.requestChanges(project,new ReviewDecisionRequest("TEST_ONLY return"),reviewer));String next=jdbc.queryForObject("select id from script_versions where project_id=? and is_current",String.class,project);var copied=stem.get(project,next,writer);assertThat(copied.evidence()).hasSize(1);assertThat(copied.evidence().get(0).sceneId()).isNotEqualTo(scene);assertThat(jdbc.queryForObject("select version_id from scenes where id=?",String.class,copied.evidence().get(0).sceneId())).isEqualTo(next);assertThat(jdbc.queryForObject("select count(*) from stem_assessments where version_id=?",Integer.class,next)).isZero();}
 @Test void staleApproveWritesNeitherDecisionNorAssessment(){create();tx.execute(s->scripts.submitForReview(project,writer));assertThatThrownBy(()->tx.execute(s->scripts.approve(project,new ReviewDecisionRequest("TEST_ONLY",assessment(3,"approve-stale-01")),reviewer))).isInstanceOf(ApiException.class);assertThat(jdbc.queryForObject("select count(*) from status_histories where project_id=? and decision='APPROVED'",Integer.class,project)).isZero();assertThat(jdbc.queryForObject("select count(*) from stem_assessments where version_id=?",Integer.class,version)).isZero();}
 @Test void clientsHaveNoRlsReadOrWritePolicy(){String role="stem_p3_test_client";tx.executeWithoutResult(s->{jdbc.execute("create role "+role);jdbc.execute("grant select,insert on stem_catalog to "+role);jdbc.execute("set local role "+role);assertThat(jdbc.queryForObject("select count(*) from stem_catalog",Integer.class)).isZero();jdbc.execute("reset role");});}
 @Test void validationRateAndRunsAreIsolated(){create();for(int i=0;i<10;i++)stem.validate(project,version,writer,new StemDtos.Validate(0,0,"SCRIPT",null));assertThatThrownBy(()->stem.validate(project,version,writer,new StemDtos.Validate(0,0,"SCRIPT",null))).isInstanceOfSatisfying(ApiException.class,e->assertThat(e.getStatus().value()).isEqualTo(429));assertThat(jdbc.queryForObject("select count(*) from stem_validation_runs r join stem_briefs b on b.id=r.brief_id where b.version_id=?",Integer.class,version)).isEqualTo(10);}
 @Test void sameKeyDifferentPayloadIsConflict(){create();stem.save(project,version,writer,save(StemDtos.empty(),List.of(),0,"same-key-01"));assertThatThrownBy(()->stem.save(project,version,writer,save(StemDtos.empty(),List.of(),1,"same-key-01"))).isInstanceOfSatisfying(ApiException.class,e->assertThat(e.getCode()).isEqualTo("STEM_IDEMPOTENCY_CONFLICT"));}
 @Test void concurrentSavesHaveOneWinner()throws Exception{create();var pool=Executors.newFixedThreadPool(2);try{List<Future<Boolean>> results=pool.invokeAll(List.of(()->attemptSave("race-key-01"),()->attemptSave("race-key-02")));assertThat(results.stream().filter(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).count()).isEqualTo(1);assertThat(stem.get(project,version,writer).revision()).isEqualTo(1);}finally{pool.shutdownNow();}}

