 @Test void pinnedOldPolicySurvivesAssignmentChange(){create();String policy=tx.execute(s->db.createDraft(StemModels.Kind.POLICY,"TEST_ONLY-"+UUID.randomUUID(),1,null,null,json.createObjectNode()));stem.saveSettings(workspace,admin,new StemDtos.Settings(0,"ADVISORY",List.of(policy),policy,"pin-mode-01",null));var b=StemDtos.empty();var pinned=new StemDtos.Brief(policy,null,null,b.subjectKeys(),b.outcomeIds(),b.scopeOfClip(),b.context(),b.distributionChannels(),b.objectives(),b.studentTasks(),b.contributions(),b.safetyNotes(),"TEST_ONLY legacy raw");stem.save(project,version,writer,save(pinned,List.of(),0,"pin-save-01"));stem.saveSettings(workspace,admin,new StemDtos.Settings(1,"OFF",List.of(),null,"pin-mode-02",null));assertThat(stem.get(project,version,writer).brief().policyVersionId()).isEqualTo(policy);assertThat(stem.get(project,version,writer).findings()).anyMatch(e->e.ruleId().equals("TECH-POLICY"));stem.save(project,version,writer,save(pinned,List.of(),1,"pin-save-02"));assertThatThrownBy(()->tx.executeWithoutResult(s->db.updateDraft(policy,0,json.createObjectNode()))).isInstanceOf(ApiException.class);}
 @Test void keyedRequestChangesRetryCannotDuplicateVersion(){create();tx.execute(s->scripts.submitForReview(project,writer));var request=new ReviewDecisionRequest("TEST_ONLY reason",null,new StemDtos.ChangeTarget(version,0,0,"change-test-01"));tx.execute(s->scripts.requestChanges(project,request,reviewer));tx.execute(s->scripts.requestChanges(project,request,reviewer));assertThat(jdbc.queryForObject("select count(*) from script_versions where project_id=?",Integer.class,project)).isEqualTo(2);assertThatThrownBy(()->tx.execute(s->scripts.requestChanges(project,new ReviewDecisionRequest("different reason",null,request.changeTarget()),reviewer))).isInstanceOfSatisfying(ApiException.class,e->assertThat(e.getCode()).isEqualTo("STEM_IDEMPOTENCY_CONFLICT"));}
