 @Test void testMigrationRejectsWrongPrerequisiteType()throws Exception{String sql=new String(new org.springframework.core.io.ClassPathResource("db/stem-p3/V91000__stem_p3_test_only.sql").getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);assertThatThrownBy(()->tx.executeWithoutResult(s->{jdbc.execute("create temporary table users(id uuid)");jdbc.execute(sql);})).isInstanceOf(org.springframework.dao.DataAccessException.class).hasMessageContaining("prerequisite drift");assertThat(jdbc.queryForObject("select count(*) from pg_class where relname='stem_catalog'",Integer.class)).isEqualTo(1);}
