 @org.junit.jupiter.params.ParameterizedTest
 @org.junit.jupiter.params.provider.ValueSource(booleans={true,false})
 void bothVideoBranchesUseSameAssessmentGuardAndRetry(boolean hasClip){
  create();String compId=UUID.randomUUID().toString();jdbc.update("insert into compositions(id,script_version_id,project_id,revision,scenes) values(?::uuid,?,?,1,'[]')",compId,version,project);jdbc.update("update clip_projects set script_status='APPROVED',video_status='IN_QA' where id=?",project);jdbc.update("update script_versions set status='APPROVED' where id=?",version);
  var cp=mock(com.stemotion.domain.production.service.CompositionService.class);var render=mock(com.stemotion.domain.production.service.RenderService.class);var artifacts=mock(com.stemotion.domain.production.service.ClipArtifactService.class);var notes=mock(com.stemotion.domain.review.repository.FeedbackCommentRepository.class);
  var composition=com.stemotion.domain.production.entity.Composition.builder().revision(1).build();composition.setId(compId);when(cp.ensure(any(),any(),anyString())).thenReturn(composition);when(cp.renderInput(any())).thenReturn(new com.stemotion.domain.production.service.CompositionService.RenderInput(composition,1,List.of()));
  if(hasClip){String jobId=UUID.randomUUID().toString(),clipId=UUID.randomUUID().toString();jdbc.update("insert into render_jobs(id,created_at,updated_at,project_id,version_id,requested_by,status,resolution,fps,composition_id,composition_revision) values(?,current_timestamp,current_timestamp,?,?,?,'COMPLETED','RES_1080P',30,?::uuid,1)",jobId,project,version,reviewer,compId);jdbc.update("insert into clips(id,render_job_id,video_url) values(?::uuid,?,?)",clipId,jobId,"http://127.0.0.1/TEST_ONLY-not-real.mp4");var job=com.stemotion.domain.production.entity.RenderJob.builder().compositionRevision(1).build();job.setId(jobId);var clip=com.stemotion.domain.production.entity.Clip.builder().renderJob(job).build();clip.setId(clipId);when(artifacts.findCurrent(any(),anyString())).thenReturn(Optional.of(clip));}else when(artifacts.findCurrent(any(),anyString())).thenReturn(Optional.empty());
  var auth=mock(AuthService.class);when(auth.findUserOrThrow(anyString())).thenAnswer(i->users.findById(i.getArgument(0)).orElseThrow());var service=new com.stemotion.domain.review.service.FeedbackService(notes,scenes,projects,scripts,auth,artifacts,new StatusHistoryService(history),cp,render);ReflectionTestUtils.setField(service,"stem",stem);
  var request=new StemDtos.Assessment(0,0,1,0,null,List.of(new StemDtos.Criterion("TEST_ONLY","NOT_ASSESSED","TEST_ONLY",List.of())),"video-approve-01");
  assertThatThrownBy(()->tx.executeWithoutResult(s->service.approveVideo(project,admin,"TEST_ONLY",request))).isInstanceOfSatisfying(ApiException.class,e->assertThat(e.getStatus().value()).isEqualTo(403));
  tx.executeWithoutResult(s->service.approveVideo(project,reviewer,"TEST_ONLY",request));tx.executeWithoutResult(s->service.approveVideo(project,reviewer,"TEST_ONLY",request));assertThat(jdbc.queryForObject("select count(*) from stem_assessments where version_id=? and phase='VIDEO'",Integer.class,version)).isEqualTo(1);verify(render,times(hasClip?0:1)).renderApproved(project,reviewer);
 }
