 @Test void legacyDepartmentLibrarySuggestsChannelWithoutInferringPrimary(){create();var b=StemDtos.empty();var legacy=new StemDtos.Brief(null,null,null,b.subjectKeys(),b.outcomeIds(),null,b.context(),b.distributionChannels(),b.objectives(),b.studentTasks(),b.contributions(),null,"DEPARTMENT_LIBRARY");var result=stem.save(project,version,writer,save(legacy,List.of(),0,"legacy-context-01"));assertThat(result.brief().context().primary()).isNull();assertThat(result.brief().distributionChannels()).isEmpty();assertThat(result.legacySuggestion().channelKeys()).containsExactly("DEPARTMENT_LIBRARY");assertThat(result.readiness()).isEqualTo("LEGACY_UNMAPPED");}

 @Test void legacyAdminApprovalWithoutAssessmentStaysLegacy(){create();tx.execute(s->scripts.submitForReview(project,writer));tx.execute(s->scripts.approve(project,new ReviewDecisionRequest("TEST_ONLY legacy decision"),admin));assertThat(jdbc.queryForObject("select count(*) from stem_assessments where version_id=?",Integer.class,version)).isZero();assertThat(stem.get(project,version,writer).verificationStatus()).isEqualTo("UNVERIFIED");}
 @Test void crossWorkspaceOrVersionCannotBeReadThroughApi()throws Exception{String[] other=tx.execute(s->{var a=users.findById(admin).orElseThrow();var ws=workspaces.saveAndFlush(Workspace.builder().name("TEST_ONLY other").createdBy(a).build());var cp=projects.saveAndFlush(ClipProject.builder().title("TEST_ONLY private").subject(StemSubject.Math).owner(a).workspace(ws).build());var sv=versions.saveAndFlush(ScriptVersion.builder().project(cp).title("TEST_ONLY private").versionNo(1).createdBy(a).build());return new String[]{cp.getId(),sv.getId()};});mvc.perform(get("/api/v1/scripts/{p}/versions/{v}/stem",other[0],other[1]).principal(()->writer)).andExpect(status().isForbidden());mvc.perform(get("/api/v1/scripts/{p}/versions/{v}/stem",project,other[1]).principal(()->writer)).andExpect(status().isForbidden());}
 @Test void outcomeGradeMismatchIsRejectedWithoutPromotingContent(){create();String source=tx.execute(s->db.createDraft(StemModels.Kind.SOURCE_EDITION,"TEST_ONLY-source-"+UUID.randomUUID(),1,null,null,json.createObjectNode().put("provenance","TEST_ONLY")));String outcome=tx.execute(s->db.createDraft(StemModels.Kind.OUTCOME,"TEST_ONLY-outcome-"+UUID.randomUUID(),1,null,source,json.createObjectNode().put("gradeKey","TEST_ONLY-grade4").put("subjectKey","TEST_ONLY-science")));var b=StemDtos.empty();var wrong=new StemDtos.Brief(null,null,"TEST_ONLY-grade8",List.of("TEST_ONLY-science"),List.of(outcome),null,b.context(),b.distributionChannels(),b.objectives(),b.studentTasks(),b.contributions(),null,null);assertThatThrownBy(()->stem.save(project,version,writer,save(wrong,List.of(),0,"grade-mismatch-01"))).isInstanceOfSatisfying(ApiException.class,e->assertThat(e.getDetails()).containsEntry("field","brief.outcomeIds"));assertThat(stem.get(project,version,writer).revision()).isZero();}
 com.stemotion.domain.script.dto.SceneDtos.SceneRequest requestScene(String id){var x=new com.stemotion.domain.script.dto.SceneDtos.SceneRequest();x.setId(id);x.setType(SceneType.TITLE_HERO);x.setTitle("TEST_ONLY");x.setNarration("TEST_ONLY");x.setDurationInFrames(90);for(String key:List.of("subtitle","subject","gradeLevel","badgeText"))x.putProp(key,"TEST_ONLY");return x;}
 @Test void reorderInsertAndDeleteNeverRetargetExistingEvidence(){create();String second=tx.execute(s->scenes.saveAndFlush(Scene.builder().scriptVersion(versions.findById(version).orElseThrow()).sceneType(SceneType.TITLE_HERO).title("TEST_ONLY same title").narration("TEST_ONLY").props("{}").orderNo(2).build()).getId());stem.save(project,version,writer,save(StemDtos.empty(),List.of(new StemDtos.Evidence(null,scene,null,null,"M","TEST_ONLY")),0,"reorder-evidence-01"));tx.execute(s->scripts.updateDraft(project,new UpdateScriptRequest(null,null,null,null,null,List.of(requestScene(second),requestScene(scene)),0)));assertThat(stem.get(project,version,writer).evidence().get(0).sceneId()).isEqualTo(scene);assertThat(jdbc.queryForObject("select order_no from scenes where id=?",Integer.class,scene)).isEqualTo(2);tx.execute(s->scripts.updateDraft(project,new UpdateScriptRequest(null,null,null,null,null,List.of(requestScene("local-test-insert"),requestScene(second),requestScene(scene)),1)));String inserted=jdbc.queryForObject("select id from scenes where version_id=? and id<>? and id<>?",String.class,version,scene,second);assertThat(stem.get(project,version,writer).evidence()).noneMatch(e->inserted.equals(e.sceneId()));tx.execute(s->scripts.updateDraft(project,new UpdateScriptRequest(null,null,null,null,null,List.of(requestScene(inserted),requestScene(second)),2)));assertThat(stem.get(project,version,writer).evidence().get(0).sceneId()).isEqualTo(scene);assertThat(stem.get(project,version,writer).findings()).anyMatch(e->e.ruleId().equals("TECH-EVIDENCE"));}
 boolean attemptSave(String key){try{stem.save(project,version,writer,save(StemDtos.empty(),List.of(),0,key));return true;}catch(ApiException e){assertThat(e.getStatus().value()).isEqualTo(409);return false;}}
